def matrix_minor(a, remove_row, remove_col):
    return [
        [x for j, x in enumerate(row) if j != remove_col]
        for i, row in enumerate(a)
        if i != remove_row
    ]


def det(a):
    n = len(a)
    if n == 0:
        return F(1)
    m = [[F(x) for x in row] for row in a]
    sign = 1
    out = F(1)
    for c in range(n):
        pivot = next((r for r in range(c, n) if m[r][c] != 0), None)
        if pivot is None:
            return F(0)
        if pivot != c:
            m[c], m[pivot] = m[pivot], m[c]
            sign *= -1
        p = m[c][c]
        out *= p
        for r in range(c + 1, n):
            if m[r][c] == 0:
                continue
            factor = m[r][c] / p
            for j in range(c + 1, n):
                m[r][j] -= factor * m[c][j]
            m[r][c] = F(0)
    return out * sign


def rank(a):
    m = [[F(x) for x in row] for row in a]
    rows = len(m)
    cols = len(m[0]) if rows else 0
    r = 0
    for c in range(cols):
        pivot = next((i for i in range(r, rows) if m[i][c] != 0), None)
        if pivot is None:
            continue
        m[r], m[pivot] = m[pivot], m[r]
        p = m[r][c]
        for j in range(c, cols):
            m[r][j] /= p
        for i in range(rows):
            if i == r or m[i][c] == 0:
                continue
            factor = m[i][c]
            for j in range(c, cols):
                m[i][j] -= factor * m[r][j]
        r += 1
        if r == rows:
            break
    return r


def solve(a, b):
    n = len(a)
    aug = [[F(x) for x in a[i]] + [F(b[i])] for i in range(n)]
    for c in range(n):
        pivot = next((r for r in range(c, n) if aug[r][c] != 0), None)
        if pivot is None:
            raise ValueError("singular")
        aug[c], aug[pivot] = aug[pivot], aug[c]
        p = aug[c][c]
        for j in range(c, n + 1):
            aug[c][j] /= p
        for r in range(n):
            if r == c or aug[r][c] == 0:
                continue
            f = aug[r][c]
            for j in range(c, n + 1):
                aug[r][j] -= f * aug[c][j]
    return [aug[i][n] for i in range(n)]


def graph_record(n, pairs, label):
    candidates = [
        F(2, 3), F(3, 5), F(4, 7), F(5, 8), F(7, 9), F(3, 2),
        F(5, 3), F(7, 4), F(8, 5), F(9, 7), F(11, 6), F(13, 8),
        F(5, 2), F(7, 3), F(11, 5), F(13, 6), F(17, 9),
    ]
    local = random.Random(int.from_bytes(hashlib.sha256(SEED + label.encode()).digest(), "big"))
    local.shuffle(candidates)
    edges = []
    for k, (u, v) in enumerate(pairs):
        w = candidates[k % len(candidates)]
        edges.append({"u": u, "v": v, "conductance": frac_input(w)})
    return {"n": n, "edges": edges}


