class Context:
    def __init__(self, graph, source, target):
        self.graph = graph
        self.n = graph["n"]
        self.source = source
        self.target = target
        self.edges = [(e["u"], e["v"], F(str(e["conductance"]))) for e in graph["edges"]]
        self.a = [[F(0) for _ in range(self.n)] for _ in range(self.n)]
        for u, v, w in self.edges:
            self.a[u][v] = w
            self.a[v][u] = w
        self.deg = [sum(row, F(0)) for row in self.a]
        self.lap = [
            [(self.deg[i] if i == j else F(0)) - self.a[i][j] for j in range(self.n)]
            for i in range(self.n)
        ]
        self.comps = self._components()
        self.connected = len(self.comps) == 1
        self.term_connected = any(source in c and target in c for c in self.comps)
        self.edge_w = self.a[source][target]
        self._tree_cache = None
        self.cache = {}

    def _components(self):
        unseen = set(range(self.n))
        out = []
        while unseen:
            start = min(unseen)
            todo = [start]
            unseen.remove(start)
            comp = []
            while todo:
                u = todo.pop()
                comp.append(u)
                for v in range(self.n):
                    if self.a[u][v] and v in unseen:
                        unseen.remove(v)
                        todo.append(v)
            out.append(sorted(comp))
        return out

    def _trees(self):
        if self._tree_cache is not None:
            return self._tree_cache
        tau = F(0)
        edge_mass = F(0)
        for inds in itertools.combinations(range(len(self.edges)), self.n - 1):
            parent = list(range(self.n))

            def find(x):
                while parent[x] != x:
                    parent[x] = parent[parent[x]]
                    x = parent[x]
                return x

            ok = True
            wt = F(1)
            has_terminal = False
            for i in inds:
                u, v, w = self.edges[i]
                ru, rv = find(u), find(v)
                if ru == rv:
                    ok = False
                    break
                parent[ru] = rv
                wt *= w
                if {u, v} == {self.source, self.target}:
                    has_terminal = True
            if ok and len({find(i) for i in range(self.n)}) == 1:
                tau += wt
                if has_terminal:
                    edge_mass += wt
        self._tree_cache = tau, edge_mass
        return self._tree_cache

    def _component_for_terminals(self):
        for c in self.comps:
            if self.source in c and self.target in c:
                return c
        return None

    def _electrical_component(self):
        verts = self._component_for_terminals()
        if verts is None:
            return Undefined("terminals_disconnected")
        reduced = [v for v in verts if v != self.target]
        mat = [[self.lap[i][j] for j in reduced] for i in reduced]
        rhs = [F(1) if i == self.source else F(0) for i in reduced]
        vals = solve(mat, rhs)
        potential = {v: x for v, x in zip(reduced, vals)}
        potential[self.target] = F(0)
        return potential

    def _hitting(self, start, target):
        comp = next((c for c in self.comps if start in c and target in c), None)
        if comp is None:
            return Undefined("terminals_disconnected")
        unknown = [v for v in comp if v != target]
        mat = []
        rhs = []
        for i in unknown:
            row = []
            for j in unknown:
                pij = self.a[i][j] / self.deg[i]
                row.append((F(1) if i == j else F(0)) - pij)
            mat.append(row)
            rhs.append(F(1))
        sol = solve(mat, rhs)
        return sol[unknown.index(start)]

    def _period(self):
        if not self.connected:
            return Undefined("period_requires_connected")
        color = {}
        parent = {}
        for start in range(self.n):
            if start in color:
                continue
            color[start] = 0
            parent[start] = None
            todo = [start]
            while todo:
                u = todo.pop(0)
                for v in range(self.n):
                    if not self.a[u][v]:
                        continue
                    if v not in color:
                        color[v] = 1 - color[u]
                        parent[v] = u
                        todo.append(v)
                    elif color[v] == color[u]:
                        # Find a lexicographically stable odd simple cycle by brute force.
                        verts = range(self.n)
                        cycles = []
                        for length in range(3, self.n + 1, 2):
                            for perm in itertools.permutations(verts, length):
                                if perm[0] != min(perm):
                                    continue
                                if all(self.a[perm[k]][perm[(k + 1) % length]] for k in range(length)):
                                    rev = (perm[0],) + tuple(reversed(perm[1:]))
                                    canonical = min(tuple(perm), rev)
                                    cycles.append(canonical)
                            if cycles:
                                cyc = min(cycles)
                                return F(1), {"kind": "odd_cycle", "vertices": list(cyc) + [cyc[0]]}
                        raise AssertionError("non-bipartite graph without odd cycle")
        sides = [sorted([v for v, c in color.items() if c == k]) for k in (0, 1)]
        if sides[1] < sides[0]:
            sides.reverse()
        return F(2), {"kind": "bipartition", "sides": sides}

    def get(self, name):
        if name in self.cache:
            return self.cache[name]
        n = self.n
        if name == "n":
            val = F(n)
        elif name == "edge_count":
            val = F(len(self.edges))
        elif name == "total_conductance":
            val = sum(self.deg, F(0))
        elif name == "degrees":
            val = list(self.deg)
        elif name == "laplacian":
            val = self.lap
        elif name == "transition_matrix":
            val = Undefined("zero_degree_vertex") if any(d == 0 for d in self.deg) else [
                [self.a[i][j] / self.deg[i] for j in range(n)] for i in range(n)
            ]
        elif name == "laplacian_rw":
            p = self.get("transition_matrix")
            val = p if is_undef(p) else [
                [(F(1) if i == j else F(0)) - p[i][j] for j in range(n)] for i in range(n)
            ]
        elif name == "laplacian_rank":
            val = F(rank(self.lap))
        elif name == "laplacian_determinant":
            val = det(self.lap)
        elif name == "target_cofactor":
            val = det(matrix_minor(self.lap, self.target, self.target))
        elif name == "nonzero_spectrum_product":
            val = Undefined("connected_required") if not self.connected else sum(
                (det(matrix_minor(self.lap, i, i)) for i in range(n)), F(0)
            )
        elif name == "rw_nonzero_spectrum_product":
            lrw = self.get("laplacian_rw")
            val = Undefined("connected_required") if not self.connected or is_undef(lrw) else sum(
                (det(matrix_minor(lrw, i, i)) for i in range(n)), F(0)
            )
        elif name == "tree_mass":
            val = self._trees()[0]
        elif name == "tree_edge_mass":
            val = self._trees()[1] if self.connected and self.edge_w > 0 else Undefined("existing_edge_and_connected_required")
        elif name == "edge_probability":
            val = self._trees()[1] / self._trees()[0] if self.connected and self.edge_w > 0 else Undefined("existing_edge_and_connected_required")
        elif name == "stationary_measure":
            val = list(self.deg)
        elif name == "stationary_distribution":
            vol = sum(self.deg, F(0))
            val = Undefined("zero_degree_vertex") if any(d == 0 for d in self.deg) else [d / vol for d in self.deg]
        elif name == "resistance":
            ep = self._electrical_component()
            val = ep if is_undef(ep) else ep[self.source] - ep[self.target]
        elif name == "hit_forward":
            val = self._hitting(self.source, self.target)
        elif name == "hit_backward":
            val = self._hitting(self.target, self.source)
        elif name == "commute":
            hf, hb = self.get("hit_forward"), self.get("hit_backward")
            val = hf if is_undef(hf) else hb if is_undef(hb) else hf + hb
        elif name == "potentials":
            if not self.connected:
                val = Undefined("global_potentials_require_connected")
            else:
                ep = self._electrical_component()
                val = [ep[i] for i in range(n)]
        elif name == "ones":
            val = [F(1) for _ in range(n)]
        elif name == "connected":
            val = self.connected
        elif name == "terminals_connected":
            val = self.term_connected
        elif name == "terminal_is_edge":
            val = self.edge_w > 0
        elif name == "period":
            period_result = self._period()
            val = period_result if is_undef(period_result) else period_result[0]
        else:
            val = Undefined("unknown_quantity")
        self.cache[name] = val
        return val

    def certificate(self):
        p = self._period()
        return None if is_undef(p) else p[1]


def value_type(v):
    if is_undef(v):
        return "undefined"
    if type(v) is bool:
        return "boolean"
    if isinstance(v, F):
        return "rational"
    if isinstance(v, list):
        if not v or all(isinstance(x, F) for x in v):
            return "vector"
        if all(isinstance(row, list) and all(isinstance(x, F) for x in row) for row in v):
            return "matrix"
    return "bad"


def eval_expr(expr, ctx):
    kind = expr.get("kind")
    if kind == "rational":
        try:
            val = expr["value"]
            if type(val) is bool or not isinstance(val, (int, str)):
                return Undefined("rational_type")
            return F(str(val))
        except Exception:
            return Undefined("malformed_rational")
    if kind == "boolean":
        return expr["value"] if type(expr.get("value")) is bool else Undefined("boolean_type")
    if kind == "quantity":
        return ctx.get(expr["name"])
    if kind == "entry":
        arg = eval_expr(expr["arg"], ctx)
        if is_undef(arg):
            return arg
        try:
            out = arg
            for i in expr["indices"]:
                out = out[i]
            return out
        except Exception:
            return Undefined("entry_error")
    if kind == "unary":
        arg = eval_expr(expr["arg"], ctx)
        if is_undef(arg):
            return arg
        op = expr["op"]
        if op == "neg" and isinstance(arg, F):
            return -arg
        if op == "not" and type(arg) is bool:
            return not arg
        if op in ("sum", "product") and value_type(arg) == "vector":
            if op == "sum":
                return sum(arg, F(0))
            out = F(1)
            for x in arg:
                out *= x
            return out
        return Undefined("unary_type")
    if kind == "binary":
        left = eval_expr(expr["left"], ctx)
        right = eval_expr(expr["right"], ctx)
        if is_undef(left):
            return left
        if is_undef(right):
            return right
        op = expr["op"]
        if op in ("add", "sub", "mul", "div", "lt", "le"):
            if not isinstance(left, F) or not isinstance(right, F):
                return Undefined("binary_scalar_type")
            if op == "add":
                return left + right
            if op == "sub":
                return left - right
            if op == "mul":
                return left * right
            if op == "div":
                return Undefined("division_by_zero") if right == 0 else left / right
            if op == "lt":
                return left < right
            return left <= right
        if op in ("eq", "ne"):
            if value_type(left) != value_type(right):
                return Undefined("equality_type")
            return (left == right) if op == "eq" else (left != right)
        if op in ("and", "or"):
            if type(left) is not bool or type(right) is not bool:
                return Undefined("boolean_type")
            return (left and right) if op == "and" else (left or right)
        return Undefined("unknown_operator")
    return Undefined("unknown_expression_kind")


def typed(v):
    typ = value_type(v)
    if typ == "undefined":
        return {"type": "undefined", "reason": v.reason}
    if typ == "boolean":
        return {"type": "boolean", "value": v}
    if typ == "rational":
        return {"type": "rational", "value": f"{v.numerator}/{v.denominator}"}
    if typ == "vector":
        return {"type": "vector", "value": [f"{x.numerator}/{x.denominator}" for x in v]}
    if typ == "matrix":
        return {"type": "matrix", "value": [[f"{x.numerator}/{x.denominator}" for x in row] for row in v]}
    raise TypeError(typ)


def collect_quantities(expr, out=None):
    out = set() if out is None else out
    if isinstance(expr, dict):
        if expr.get("kind") == "quantity" and isinstance(expr.get("name"), str):
            out.add(expr["name"])
        for v in expr.values():
            collect_quantities(v, out)
    elif isinstance(expr, list):
        for v in expr:
            collect_quantities(v, out)
    return out


