def evaluate_input(inp):
    ctx = Context(inp["graph"], inp["source"], inp["target"])
    assumptions = []
    for rec in inp["assumptions"]:
        val = eval_expr(rec["expression"], ctx)
        assumptions.append({"id": rec["id"], "value": typed(val)})
    interp = inp["provenance"]["interpretation"]
    if interp in ("ambiguous", "unsupported"):
        verdict = "abstain"
        claim_val = Undefined("interpretation_not_explicit")
    else:
        raw_vals = [eval_expr(r["expression"], ctx) for r in inp["assumptions"]]
        if any(type(v) is bool and not v for v in raw_vals):
            verdict = "not_applicable"
            claim_val = eval_expr(inp["claim"], ctx)
        elif any(is_undef(v) or type(v) is not bool for v in raw_vals):
            verdict = "abstain"
            claim_val = eval_expr(inp["claim"], ctx)
        else:
            claim_val = eval_expr(inp["claim"], ctx)
            if is_undef(claim_val) or type(claim_val) is not bool:
                verdict = "abstain"
            else:
                verdict = "no_counterexample_in_instance" if claim_val else "counterexample"
    qs = set()
    for a in inp["assumptions"]:
        collect_quantities(a["expression"], qs)
    collect_quantities(inp["claim"], qs)
    return {
        "expected_verdict": verdict,
        "expected_error_class": None,
        "expected_assumptions": assumptions,
        "expected_claim_value": typed(claim_val),
        "expected_referenced_values": {name: typed(ctx.get(name)) for name in sorted(qs)},
        "expected_period_certificate": ctx.certificate() if "period" in qs and ctx.connected else None,
    }


def add_valid(partition, theme, graph_name, source, target, assumptions, claim, expected, kind="source_annotation", interpretation="explicit", pair=None):
    cid = f"H{len(cases)+1:03d}"
    inp = {
        "id": cid,
        "graph": copy.deepcopy(graphs[graph_name]),
        "source": source,
        "target": target,
        "provenance": provenance(cid, theme, kind, interpretation),
        "assumptions": [{"id": aid, "expression": ex} for aid, ex in assumptions],
        "claim": claim,
    }
    gold = evaluate_input(inp)
    assert gold["expected_verdict"] == expected, (cid, theme, gold["expected_verdict"], expected)
    cases.append({
        "case_id": cid,
        "partition": partition,
        "theme": theme,
        "pair": pair,
        "input": inp,
        "gold": gold,
    })


